mapper.select:
select
#{uid} uid, s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type,
s.signing_data, s.validity_Date, s.first_person_id,  s.second_person_id, s.third_person_id, fourth_person_id,
concat( s.amount,'万') amount, s.contract, s.filing, s.state ,s.PA ,s.PB
from sci_IntraSchPro_apply s left join sys_user u on  s.user_id=u.user_id
left join sys_dept d on u.dept_id = d.dept_id
left join sys_dept p on d.parent_id =p.dept_id
where s.state = 6
AND (
s.user_id = #{uid}
OR s.first_person_id = #{uid}
OR s.second_person_id = #{uid}
OR s.third_person_id = #{uid}
OR s.fourth_person_id = #{uid}
)

 and top_name like concat('%', #{topName}, '%')

 and user_name like concat('%', #{userName}, '%')
 and state = #{state}

 and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}


/*${params.dataScope}*/
order  by createtime desc

 select
 'sci_tesearch' role,#{uid} uid, s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type,
 s.signing_data, s.validity_Date, s.first_person_id,  s.second_person_id, s.third_person_id, fourth_person_id,
 concat( s.amount,'万') amount, s.contract, s.filing, s.state ,s.PA ,s.PB
 from sci_IntraSchPro_apply s left join sys_user u on  s.user_id=u.user_id
 left join sys_dept d on u.dept_id = d.dept_id
 left join sys_dept p on d.parent_id =p.dept_id


where s.state in (2,4,1,3,11,12)
OR (
s.user_id = #{uid}
OR s.first_person_id = #{uid}
OR s.second_person_id = #{uid}
OR s.third_person_id = #{uid}
OR s.fourth_person_id = #{uid}
)


  and top_name like concat('%', #{topName}, '%')

  and user_name like concat('%', #{userName}, '%')
  and state = #{state}

  and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}



 order  by createtime desc

select
'research' role,#{uid} uid,(SELECT dept_name FROM sys_dept WHERE dept_id=(SELECT dept_id from sys_user WHERE user_id=#{uid}))=d.dept_name deptNamekey, s.id,u.user_name userName,d.dept_name dname,p.dept_name yname, s.user_id, s.top_name, s.top_type,
s.signing_data, s.validity_Date, s.first_person_id,  s.second_person_id, s.third_person_id, fourth_person_id,
concat( s.amount,'万') amount, s.contract, s.filing, s.state ,s.PA ,s.PB
from sci_IntraSchPro_apply s left join sys_user u on  s.user_id=u.user_id
left join sys_dept d on u.dept_id = d.dept_id
left join sys_dept p on d.parent_id =p.dept_id
/*todo:这里之前只是1，3为了查到负责人包含自己的，该成了1,2,3,4,5,之后在前端判断一下这个项目的状态，然后加一个按钮可以查看详情*/

where s.state in (1,11,2,3,4,12)

${params.dataScope}
or (
s.user_id = #{uid}
OR s.first_person_id = #{uid}
OR s.second_person_id = #{uid}
OR s.third_person_id = #{uid}
OR s.fourth_person_id = #{uid}
)

 and top_name like concat('%', #{topName}, '%')

 and user_name like concat('%', #{userName}, '%')
 and state = #{state}

 and YEAR(DATE_ADD(signing_data,INTERVAL 1 MONTH)) = #{year}


order  by createtime desc

